package com.wandertrace.controller;
import com.wandertrace.dto.*;import com.wandertrace.dto.AuthDtos.*;import com.wandertrace.security.CurrentUser;import com.wandertrace.service.AuthService;import jakarta.servlet.http.HttpSession;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;private final CurrentUser current;public AuthController(AuthService auth,CurrentUser current){this.auth=auth;this.current=current;}@PostMapping("/register")@ResponseStatus(HttpStatus.CREATED) public ApiResponse<User> register(@Valid @RequestBody Registration request,HttpSession s){return ApiResponse.ok(auth.register(request,s));}@PostMapping("/login")public ApiResponse<User> login(@Valid @RequestBody Credentials request,HttpSession s){return ApiResponse.ok(auth.login(request,s));}@PostMapping("/logout")public ApiResponse<Void> logout(HttpSession s){auth.logout(s);return ApiResponse.ok(null);}@GetMapping("/me")public ApiResponse<User> me(HttpSession s){return ApiResponse.ok(auth.me(current.require(s)));}}
